.seatmap { --sm-ink: #182839; --sm-muted: #6b7989; --sm-line: #e4eaf0; --sm-blue: #225fe8; box-sizing: border-box; width: 100%; height: 680px; min-width: 280px; display: flex; flex-direction: column; overflow: hidden; color: var(--sm-ink); background: rgb(255, 255, 255); border: 1px solid rgb(220, 228, 237); border-radius: 22px; font: 14px / 1.4 Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; box-shadow: rgba(21, 41, 67, 0.04) 0px 12px 40px; }.seatmap *, .seatmap ::before, .seatmap ::after { box-sizing: border-box; }.seatmap button, .seatmap input { font: inherit; }.seatmap button { -webkit-tap-highlight-color: transparent; }.seatmap button:focus-visible, .seatmap input:focus-visible, .seatmap-grid-scroll:focus-visible { outline: rgb(137, 179, 255) solid 3px; outline-offset: 3px; }.seatmap-header { flex: 0 0 auto; display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; padding: 19px 24px 15px; }.seatmap-brand { display: flex; align-items: center; gap: 6px; font-size: 10px; font-weight: 800; letter-spacing: 1.5px; color: rgb(54, 83, 109); }.seatmap-brandmark { width: 22px; height: 22px; display: grid; place-items: center; border-radius: 7px; background: rgb(234, 241, 255); color: var(--sm-blue); font-size: 17px; line-height: 1; }.seatmap-flight { align-self: center; font-size: 10px; color: var(--sm-muted); white-space: nowrap; }.seatmap-heading { grid-column: 1 / -1; display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-top: 3px; }.seatmap-heading h2 { margin: 0px; color: var(--sm-ink); font-size: 24px; line-height: 1.15; font-weight: 750; letter-spacing: -0.8px; }.seatmap-route { white-space: nowrap; font-size: 12px; font-weight: 700; letter-spacing: 0.7px; }.seatmap-route > span { margin: 0px 5px; color: rgb(138, 154, 173); font-size: 16px; }.seatmap-subtitle { grid-column: 1 / -1; margin: 0px; font-size: 11px; color: var(--sm-muted); }.seatmap-subtitle > span { padding: 0px 4px; }.seatmap-legend { flex: 0 0 auto; display: flex; justify-content: space-between; gap: 6px; padding: 12px 24px; border-top: 1px solid var(--sm-line); border-bottom: 1px solid var(--sm-line); background: rgb(251, 252, 254); }.seatmap-legend > span { display: flex; align-items: center; gap: 5px; color: rgb(101, 117, 135); font-size: 10px; white-space: nowrap; }.seatmap-key { width: 12px; height: 12px; flex: 0 0 12px; display: inline-flex; justify-content: center; align-items: center; border-radius: 4px; font-size: 13px; font-style: normal; line-height: 1; }.seatmap-key-available { border: 1.3px solid rgb(156, 175, 192); background: white; }.seatmap-key-extra { border: 1.3px solid rgb(108, 185, 177); background: rgb(232, 247, 244); }.seatmap-key-selected { border: 1.3px solid var(--sm-blue); background: var(--sm-blue); }.seatmap-key-taken { background: rgb(231, 236, 242); color: rgb(158, 172, 185); }.seatmap-cabin { flex: 1 1 0px; min-height: 140px; padding: 0px 24px; background: linear-gradient(90deg, rgb(250, 252, 254), rgb(255, 255, 255) 13%, rgb(255, 255, 255) 87%, rgb(250, 252, 254)); }.seatmap-grid-scroll { height: 100%; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: rgb(205, 217, 229) transparent; padding-right: 8px; }.seatmap-column-labels, .seatmap-row { display: grid; grid-template-columns: 23px repeat(3, minmax(24px, 1fr)) 28px repeat(3, minmax(24px, 1fr)); align-items: center; gap: 9px; }.seatmap-column-labels { position: sticky; top: 0px; z-index: 1; height: 37px; margin-bottom: 3px; background: rgb(255, 254, 252); color: rgb(132, 146, 162); font-size: 10px; font-weight: 700; text-align: center; }.seatmap-aisle-label { font-size: 6px; letter-spacing: 0.7px; color: rgb(176, 186, 197); }.seatmap-row { min-height: 43px; }.seatmap-row-number { color: rgb(135, 148, 162); font-size: 10px; font-weight: 650; text-align: center; }.seatmap-aisle { font-size: 6px; letter-spacing: 0.8px; font-weight: 700; color: rgb(82, 165, 156); text-align: center; }.seatmap-seat { width: 100%; max-width: 44px; height: 33px; justify-self: center; display: flex; align-items: center; justify-content: center; padding: 4px; border: 1px solid rgb(184, 200, 215); border-radius: 8px; background: rgb(255, 255, 255); color: rgb(141, 162, 182); cursor: pointer; transition: background 0.12s, border-color 0.12s, box-shadow 0.12s; }.seatmap-seat svg { display: block; width: 22px; height: 22px; fill: none; stroke: currentcolor; stroke-width: 1.35; stroke-linecap: round; stroke-linejoin: round; }.seatmap-seat:hover:not(:disabled) { border-color: var(--sm-blue); background: rgb(237, 243, 255); box-shadow: rgb(228, 237, 255) 0px 0px 0px 2px; }.seatmap-seat.is-extra { background: rgb(237, 249, 246); border-color: rgb(135, 198, 189); color: rgb(89, 166, 155); }.seatmap-seat.is-taken { background: rgb(237, 241, 245); border-color: rgb(237, 241, 245); color: rgb(179, 190, 201); cursor: not-allowed; }.seatmap-seat.is-selected { background: var(--sm-blue); border-color: var(--sm-blue); color: white; box-shadow: rgba(34, 95, 232, 0.17) 0px 3px 7px; }.seatmap-seat.is-selected svg { stroke-width: 2.1; }.seatmap-seat.is-selected:hover:not(:disabled) { color: var(--sm-blue); }.seatmap-cabin-end { display: flex; align-items: center; justify-content: center; gap: 12px; margin: 17px 20px 18px 43px; color: rgb(169, 180, 192); font-size: 7px; letter-spacing: 1.4px; white-space: nowrap; }.seatmap-cabin-end span { height: 1px; flex: 1 1 0%; background: var(--sm-line); }.seatmap-footer { flex: 0 0 auto; display: grid; grid-template-columns: minmax(0px, 1fr) auto; column-gap: 15px; padding: 14px 24px 12px; border-top: 1px solid var(--sm-line); background: rgb(255, 255, 255); }.seatmap-selection { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-bottom: 10px; }.seatmap-selection > div { display: grid; gap: 2px; }.seatmap-eyebrow { color: rgb(139, 152, 166); font-size: 8px; font-weight: 700; letter-spacing: 1.2px; }.seatmap-selection-title { font-size: 18px; line-height: 1.2; letter-spacing: -0.35px; }.seatmap-selection-detail { color: var(--sm-muted); font-size: 10px; }.seatmap-selection-price { color: var(--sm-blue); font-size: 21px; font-weight: 750; letter-spacing: -0.5px; }.seatmap-selection-price.is-included { color: rgb(59, 136, 118); font-size: 14px; }.seatmap-name-label { grid-column: 1; display: flex; flex-wrap: wrap; justify-content: space-between; gap: 5px; font-size: 10px; font-weight: 650; color: rgb(97, 113, 132); }.seatmap-name-label > span { color: rgb(154, 167, 181); font-size: 9px; font-weight: 450; }.seatmap-name { display: block; width: 100%; height: 34px; padding: 0px 11px; color: var(--sm-ink); background: rgb(251, 252, 254); border: 1px solid rgb(219, 227, 236); border-radius: 8px; font-size: 12px !important; }.seatmap-name::placeholder { color: rgb(162, 174, 187); }.seatmap-demo-controls { grid-column: 2; display: flex; flex-direction: column; justify-content: space-between; align-items: flex-start; gap: 8px; padding: 0px 0px 2px; }.seatmap-demo-controls > label { display: flex; align-items: center; gap: 6px; color: rgb(124, 137, 152); font-size: 10px; cursor: pointer; }.seatmap-reject { width: 12px; height: 12px; margin: 0px; accent-color: var(--sm-blue); }.seatmap-reset { padding: 2px 0px; border: 0px; background: transparent; color: rgb(114, 131, 151); cursor: pointer; font-size: 10px !important; }.seatmap-reset:hover { color: var(--sm-blue); text-decoration: underline; }.seatmap-confirm { grid-column: 1 / -1; display: flex; align-items: center; justify-content: center; gap: 14px; width: 100%; height: 39px; margin-top: 11px; padding: 0px 15px; border: 0px; border-radius: 10px; background: var(--sm-blue); color: white; cursor: pointer; box-shadow: rgba(34, 95, 232, 0.1) 0px 4px 10px; font-size: 12px !important; font-weight: 700 !important; }.seatmap-confirm:hover:not(:disabled) { background: rgb(23, 79, 208); }.seatmap-confirm > span { font-size: 17px; font-weight: 400; }.seatmap-confirm > svg { width: 18px; height: 18px; fill: none; stroke: currentcolor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }.seatmap-confirm:disabled { background: rgb(232, 238, 246); color: rgb(140, 156, 175); box-shadow: none; cursor: default; }.seatmap-status { grid-column: 1 / -1; display: flex; align-items: center; min-height: 28px; margin: 5px 0px 0px; color: rgb(131, 145, 161); font-size: 9px; line-height: 1.3; }.seatmap-status[data-tone="success"] { color: rgb(38, 128, 106); }.seatmap-status[data-tone="error"] { color: rgb(189, 80, 96); }@media (max-width: 420px) {
  .seatmap-header { padding: 16px 17px 13px; gap: 8px; }
  .seatmap-heading h2 { font-size: 22px; }
  .seatmap-flight { font-size: 8px; }
  .seatmap-route { font-size: 10px; }
  .seatmap-subtitle { font-size: 9px; }
  .seatmap-legend { padding: 11px 17px; }
  .seatmap-legend > span { gap: 4px; font-size: 8px; }
  .seatmap-cabin { padding: 0px 13px; }
  .seatmap-column-labels, .seatmap-row { grid-template-columns: 20px repeat(3, minmax(20px, 1fr)) 16px repeat(3, minmax(20px, 1fr)); gap: 6px; }
  .seatmap-seat { height: 31px; border-radius: 7px; }
  .seatmap-aisle-label { font-size: 5px; letter-spacing: 0px; }
  .seatmap-footer { padding: 13px 17px 10px; }
}@media (prefers-reduced-motion: reduce) {
  .seatmap-seat { transition: none; }
}
